return {
	settings = {
		json = {
			-- vscode-json-language-server reports nothing, not even syntax errors, unless this is set
			validate = { enable = true },
			schemas = {
				{
					-- pi's settings schema plus our extensions' sections, generated by `npm run schema` in the extensions
					fileMatch = { '**/.pi/settings.json', '**/.pi/agent/settings.json' },
					url = vim.uri_from_fname(vim.fs.normalize('~/.pi/agent/extensions/settings.schema.json')),
				},
			},
		},
	},
}
